    # Momentum on asset C using a 10-step return normalized by recent volatility
    asset = 'C'
    # minimum data required
    lookback = 300
    try:
        mids = obs.hist(asset, 'mid', lookback)
    except Exception:
        return {}
    if len(mids) < lookback:
        return {}
    # ensure no nan in last few points
    if np.isnan(mids[-1]) or np.isnan(mids[-11]):
        return {}
    # 10-step returns over the lookback window
    # returns[i] = mid[i] - mid[i-10]
    if len(mids) < 11:
        return {}
    rets = np.full(len(mids), np.nan)
    # compute efficiently
    for i in range(10, len(mids)):
        if np.isnan(mids[i]) or np.isnan(mids[i-10]):
            rets[i] = np.nan
        else:
            rets[i] = mids[i] - mids[i-10]
    # use recent window for mean/std
    win = 200
    recent = rets[-win:]
    recent = recent[~np.isnan(recent)]
    if len(recent) < 50:
        return {}
    mean_ret = float(np.mean(recent))
    std_ret = float(np.std(recent))
    if std_ret <= 1e-9:
        return {}
    cur_ret = float(mids[-1] - mids[-11])
    # z-score of current 10-step return vs recent distribution
    z = (cur_ret - mean_ret) / std_ret
    # scale target to [-1,1] with a soft threshold
    thresh = 0.5
    if abs(z) < thresh:
        return {}
    # map z to position size, capped at 1
    # target magnitude grows with |z| but limited
    mag = min(1.0, abs(z) / 2.0)
    target = np.sign(z) * mag
    # avoid too large turnover by smoothing via state
    state = obs.state
    prev = state.get('prev_target', 0.0)
    # simple exponential smoothing of target
    alpha = 0.3
    smoothed = alpha * target + (1 - alpha) * prev
    state['prev_target'] = float(smoothed)
    return {asset: float(smoothed)}

